=Please identify the appropriate privacy taxonomy for this GitHub issue:

[ISSUE DETAILS]
Issue ID: {{ $('Issue1').item.json.Issue_ID }}
Title: {{ $('Issue1').item.json.Title }}
Body: {{ $('Issue1').item.json.Body }}

[REFERENCE EXAMPLES]
Here are some similar issues from our database:
{{ $json.all_formatted_examples }}

parameters.jsCode:
// Qdrant search response
const inputData = $input.first().json;
let formatted_examples = "";

// 'result' holds the retrieved examples (count = limit in the search node)
const searchResults = inputData.result || [];

searchResults.forEach((item, index) => {
    const p = item.payload || {};

    // Labels may be an array or a comma-separated string
    let labels = "None (Not a Privacy Issue)";

    if (p.true_labels) {
        if (Array.isArray(p.true_labels) && p.true_labels.length > 0) {
            labels = p.true_labels.join(", ");
        } else if (typeof p.true_labels === 'string' && p.true_labels.trim() !== '') {
            labels = p.true_labels;
        }
    }

    // Body on one line, first 200 characters
    let cleanBody = (p.body || "").replace(/\n/g, " ");
    if (cleanBody.length > 200) {
        cleanBody = cleanBody.substring(0, 200) + "...";
    }

    // Fallback for an empty title
    const title = p.title || "No Title Provided";

    formatted_examples += `Example ${index + 1}:\n`;
    formatted_examples += `Title: ${title}\n`;
    formatted_examples += `Body: ${cleanBody}\n`;
    formatted_examples += `Correct Labels: ${labels}\n`;
    formatted_examples += `-------------------\n`;
});

// Return a single item: all_formatted_examples
return [{
    json: {
        all_formatted_examples: formatted_examples
    }
}];

return items.map(item => {
  let rawOutput = item.json.output || "";

  // Strip Markdown code fences in case the model added them
  rawOutput = rawOutput.replace(/```json/gi, "").replace(/```/g, "").trim();

  try {
    // Attempt 1: Standard Parse
    const parsed = JSON.parse(rawOutput);
    return { json: formatOutput(parsed) };
  } catch (e) {
    try {
      // Attempt 2: Clean common AI mistakes (like literal newlines)
      const cleaned = rawOutput.replace(/\n/g, "\\n").replace(/\r/g, "\\r");
      const parsed = JSON.parse(cleaned);
      return { json: formatOutput(parsed) };
    } catch (e2) {
      // Return error for your Excel log
      return {
        json: {
          Issue_ID: "ERROR",
          error: "JSON Syntax Error: AI returned malformed string",
          original_output: rawOutput
        }
      };
    }
  }
});

function formatOutput(data) {
  return {
    Issue_ID: data.Issue_ID,
    Issue_Title: data.Issue_Title,
    Issue_Body: data.Issue_Body, 
    is_privacy_issue: data.is_privacy_issue || false,

    // The prompt returns Ranked_Taxonomy_IDs
    // Join as plain text for Excel, e.g. "1.1.1.1.1, 2.1, 3.2.1"
    Ranked_Taxonomy_IDs: Array.isArray(data.Ranked_Taxonomy_IDs) ? data.Ranked_Taxonomy_IDs.join(', ') : (data.Ranked_Taxonomy_IDs || ""),

    Reason: data.Reason || ""
  };
}

